import { AppThemeProvider } from '../../../../theme/theme_provider'
import { TaskProgressIndicator } from './task_progress_indicator'

const context = { cardInternalId: 'card-1', file: 'design/F-435.md', kind: 'card' as const }
const listeners: Array<(event: ActionRunEvent) => void> = []

function taskList(tasks: AgentTaskList['tasks']): AgentTaskList {
    return { tasks, updatedAt: '2026-10-20T10:00:00.000Z' }
}

function conversation(id: string, list?: AgentTaskList): AgentConversation {
    return {
        actionId: 'implement',
        cardInternalId: context.cardInternalId,
        cardPath: context.file,
        completedAt: null,
        entries: [],
        hasExplicitTitle: false,
        id,
        path: `design/activity/card.json#conversation=${id}`,
        providerSessions: [],
        startedAt: '2026-10-20T09:00:00.000Z',
        status: 'running',
        taskList: list,
        title: 'Implement',
        viewed: true,
    }
}

function emitRun(runId: string, list?: AgentTaskList) {
    const emit = listeners[0]
    if (!emit) throw new Error('Missing action run listener')
    const event = { actionId: 'implement', context, phase: 'main' as const, rootActionId: 'implement', runId, status: 'running' as const }

    act(() => {
        emit({ ...event, type: 'run' })
        emit({ ...event, type: 'update', update: { conversation: conversation(`conversation-${runId}`, list), kind: 'agentStarted' } })
    })
}

function updateTaskList(runId: string, list: AgentTaskList) {
    const emit = listeners[0]
    if (!emit) throw new Error('Missing action run listener')

    act(() => emit({
        actionId: 'implement',
        context,
        phase: 'main',
        rootActionId: 'implement',
        runId,
        status: 'running',
        type: 'update',
        update: { kind: 'agentTaskList', taskList: list },
    }))
}

function renderIndicator(runId: string) {
    return render(<TaskProgressIndicator runId={runId} />, { wrapper: AppThemeProvider })
}

describe('TaskProgressIndicator', () => {
    beforeEach(() => {
        listeners.length = 0
        setActionBridgeOverride({
            onActionRun: vi.fn((listener) => {
                listeners.push(listener)

                return vi.fn()
            }),
        } as unknown as ElectronActionBridge)
        actionRunRegistry.start()
    })

    afterEach(() => {
        cleanup()
        actionRunRegistry.stop()
        setActionBridgeOverride(null)
        vi.restoreAllMocks()
    })

    it.each([
        ['missing task list', undefined],
        ['empty task list', taskList([])],
    ])('renders nothing for a %s', (_scenario, list) => {
        emitRun('run-1', list)
        const { container } = renderIndicator('run-1')

        expect(container).toBeEmptyDOMElement()
    })

    it('shows completed task ratio as determinate accessible progress', () => {
        emitRun('run-1', taskList([
            { id: 'task-1', status: 'pending', subject: 'Inspect state' },
            { id: 'task-2', status: 'inProgress', subject: 'Write tests' },
            { id: 'task-3', status: 'completed', subject: 'Implement component' },
            { id: 'task-4', status: 'completed', subject: 'Review result' },
        ]))
        renderIndicator('run-1')

        const progress = screen.getByRole('progressbar', { name: 'Task progress: 2 of 4 completed' })
        expect(progress).toHaveAttribute('aria-valuenow', '50')
        expect(progress).toHaveAttribute('aria-valuemin', '0')
        expect(progress).toHaveAttribute('aria-valuemax', '100')
    })

    it('updates when the run publishes a replacement task list', () => {
        emitRun('run-1', taskList([
            { id: 'task-1', status: 'pending', subject: 'Inspect state' },
            { id: 'task-2', status: 'completed', subject: 'Implement component' },
        ]))
        renderIndicator('run-1')

        expect(screen.getByRole('progressbar')).toHaveAttribute('aria-valuenow', '50')

        updateTaskList('run-1', taskList([
            { id: 'task-1', status: 'completed', subject: 'Inspect state' },
            { id: 'task-2', status: 'completed', subject: 'Implement component' },
            { id: 'task-3', status: 'pending', subject: 'Review result' },
        ]))

        const progress = screen.getByRole('progressbar', { name: 'Task progress: 2 of 3 completed' })
        expect(progress).toHaveAttribute('aria-valuenow', `${2 / 3 * 100}`)
    })

    it('keeps progress scoped to its runId', () => {
        emitRun('run-1', taskList([
            { id: 'task-1', status: 'completed', subject: 'First run task' },
            { id: 'task-2', status: 'pending', subject: 'First run next task' },
        ]))
        emitRun('run-2', taskList([
            { id: 'task-1', status: 'pending', subject: 'Second run task' },
        ]))
        render(
            <>
                <TaskProgressIndicator runId="run-1" />
                <TaskProgressIndicator runId="run-2" />
            </>,
            { wrapper: AppThemeProvider },
        )

        updateTaskList('run-2', taskList([
            { id: 'task-1', status: 'completed', subject: 'Second run task' },
        ]))

        expect(screen.getByRole('progressbar', { name: 'Task progress: 1 of 2 completed' })).toHaveAttribute('aria-valuenow', '50')
        expect(screen.getByRole('progressbar', { name: 'Task progress: 1 of 1 completed' })).toHaveAttribute('aria-valuenow', '100')
    })
})

import { Box, Button, Tooltip } from '@mui/material'
import Circle from 'mdi-material-ui/Circle'
import HelpCircleOutline from 'mdi-material-ui/HelpCircleOutline'
import Play from 'mdi-material-ui/Play'
import TimerOutlined from '@mui/icons-material/TimerOutlined'
import type { MouseEvent } from 'react'
import type { ActionContext } from '../../../../data/action_context'
import type { CardHeader } from '../../../../data/data_types'
import { cardPopupService } from '../../../../services/card_popup_service'
import { agentStateDescription } from '../../../../services/agents/card_agent_state'
import { useCardAgentState } from '../../../hooks/use_agent_acknowledgements'
import { useRunningActionForContext } from '../../../hooks/use_action_runs'
import { useProjectReadOnly } from '../../../hooks/use_project_read_only'
import { usePendingActionScheduleForCard } from '../../../hooks/use_pending_action_schedule'
import { TaskProgressIndicator } from './task_progress_indicator'

interface CardRunButtonProps {
    card: { header: Pick<CardHeader, 'internalId'> }
    context: ActionContext
}

/** Opens the card action selector and run popup, and surfaces the card's agent state. */
export function CardRunButton({ card, context }: CardRunButtonProps) {
    const agentState = useCardAgentState(card.header.internalId)
    const runningRun = useRunningActionForContext(context)
    const readOnly = useProjectReadOnly()
    const scheduled = usePendingActionScheduleForCard(card.header.internalId)
    const liveStatus = runningRun?.status
    const isQueued = liveStatus === 'queued'
    const isWaiting = liveStatus ? liveStatus === 'waitingForInput' : agentState === 'waiting for input'
    const isRunning = liveStatus ? liveStatus === 'running' : agentState === 'running'
    const isUnseen = !isQueued && !isWaiting && !isRunning && agentState === 'unseen result'
    const stateDescription = isQueued
        ? 'Action is queued'
        : isWaiting
            ? agentStateDescription('waiting for input')
            : isRunning && agentState !== 'running'
                ? 'Action is running'
                : agentStateDescription(agentState)
    const showScheduled = scheduled && !isQueued && !isWaiting && !isRunning && !isUnseen
    const accent = isWaiting ? 'warning.main' : isUnseen ? 'info.main' : 'primary.main'
    const handleRun = (event: MouseEvent<HTMLButtonElement>) => {
        cardPopupService.toggleAction(context, event.currentTarget)
    }

    const button = (
        <Box
            sx={(theme) => ({
                borderRadius: 99,
                display: 'inline-flex',
                overflow: 'hidden',
                p: isRunning ? '1.5px' : 0,
                position: 'relative',
                ...(isRunning && {
                    '@keyframes md2-run-spin': { to: { transform: 'rotate(1turn)' } },
                    '&::before': {
                        animation: 'md2-run-spin 1s linear infinite',
                        background: `conic-gradient(from 0deg, ${theme.palette.primary.main}, transparent 55%)`,
                        content: '""',
                        inset: '-50%',
                        pointerEvents: 'none',
                        position: 'absolute',
                    },
                }),
            })}
        >
            <Button
                aria-label={stateDescription ? `Run â€” ${stateDescription}` : 'Run'}
                disabled={readOnly}
                onClick={handleRun}
                size="small"
                startIcon={<Play sx={{ fontSize: '13px !important' }} />}
                sx={{
                    bgcolor: 'background.paper',
                    borderColor: isRunning ? 'transparent' : isWaiting ? 'warning.main' : isUnseen ? 'info.main' : undefined,
                    borderRadius: 99,
                    color: isWaiting ? 'warning.main' : isUnseen ? 'info.main' : undefined,
                    fontSize: 11.5,
                    height: 26,
                    minWidth: 0,
                    position: 'relative',
                    px: 1.25,
                    zIndex: 1,
                    '&:hover': { bgcolor: 'background.paper' },
                }}
                variant="outlined"
            >
                Run
            </Button>
            {isWaiting ? <HelpCircleOutline sx={{ color: accent, fontSize: 11, position: 'absolute', right: -2, top: -2, zIndex: 2 }} /> : null}
            {isUnseen ? <Circle sx={{ color: accent, fontSize: 8, position: 'absolute', right: 0, top: 0, zIndex: 2 }} /> : null}
            {showScheduled ? <TimerOutlined aria-label="Action scheduled" sx={{ color: 'warning.main', fontSize: 12, position: 'absolute', right: 0, top: 0, zIndex: 2 }} /> : null}
        </Box>
    )

    return (
        <Box sx={{ display: 'inline-flex', flexDirection: 'column', gap: 0.25 }}>
            <Tooltip title={stateDescription ?? ''}>{button}</Tooltip>
            {runningRun?.status === 'running' ? <TaskProgressIndicator runId={runningRun.runId} /> : null}
        </Box>
    )
}
